class FileScanner {
  logger;
  constructor(logger) {
    this.logger = logger;
  }
  async scan(directory, options) {
    this.logger.info({ directory, patterns: options.patterns }, "Scanning directory");
    const files = [];
    for (const pattern of options.patterns) {
      const matches = await Ze(pattern, {
        cwd: directory,
        ignore: options.ignore,
        absolute: true
      });
      for (const path of matches) {
        try {
          const stats = await stat(path);
          if (options.maxFileSize && stats.size > options.maxFileSize) {
            this.logger.warn({ path, size: stats.size }, "Skipping oversized file");
            continue;
          }
          const content = await readFile(path, "utf-8");
          files.push({
            path,
            relativePath: relative(directory, path),
            content,
            size: stats.size,
            modifiedAt: stats.mtime
          });
          this.logger.debug({ path }, "File scanned");
        } catch (error) {
          this.logger.warn({ path, error }, "Failed to read file");
        }
      }
    }
    this.logger.info({ count: files.length }, "Directory scan complete");
    return files;
  }
  async getFileStats(path) {
    const stats = await stat(path);
    return {
      size: stats.size,
      modifiedAt: stats.mtime
    };
  }
}

// riffs/vector-indexer/src/core/indexer.ts
class Indexer {
  logger;
  config;
  fileScanner;
  chunker;
  metadataExtractor;
  embeddingProvider;
  sparseVectorProvider;
  qdrantProvider;
  constructor(config, logger) {
    this.config = config;
    this.logger = logger;
    this.fileScanner = new FileScanner(logger);
    this.chunker = new Chunker(config.embedding.chunking, logger);
    this.metadataExtractor = new MetadataExtractor(config.embedding.chunking.metadataExtraction, logger);
    this.embeddingProvider = new EmbeddingProvider(config, logger);
    this.sparseVectorProvider = new SparseVectorProvider(config.sparse, logger);
    this.qdrantProvider = new QdrantProvider(config.qdrant, logger);
  }
  async index(options) {
    const isDryRun = options.dryRun ?? false;
    this.logger.info({ directory: options.directory, collection: options.collection, dryRun: isDryRun }, isDryRun ? "Starting indexing (DRY RUN - no Qdrant operations)" : "Starting indexing");
    const startTime = Date.now();
    const stats = {
      documentsProcessed: 0,
      chunksCreated: 0,
      totalTokens: 0,
      errors: [],
      duration: 0,
      successRate: 0
    };
    try {
      if (!isDryRun) {
        await this.ensureCollection(options);
      }
      const files = await this.fileScanner.scan(options.directory, {
        patterns: ["**/*.md", "**/*.txt"],
        ignore: ["**/node_modules/**", "**/.git/**"]
      });
      this.logger.info({ fileCount: files.length }, "Files discovered");
      options.onScanComplete?.(files.length);
      for (let i = 0;i < files.length; i++) {
        const file = files[i];
        try {
          const result = isDryRun ? await this.processFileDryRun(file.path, file.content) : await this.processFile(file.path, file.content, options);
          stats.documentsProcessed++;
          stats.chunksCreated += result.chunksCreated;
          stats.totalTokens += result.totalTokens;
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          stats.errors.push(`${file.path}: ${message}`);
          this.logger.error({ path: file.path, error }, "Failed to process file");
        }
        options.onFileProgress?.(i + 1, files.length, file.path);
      }
      if (!isDryRun) {
        const dimensions = options.dimensions || this.config.embedding.dimensions;
        await this.qdrantProvider.updateCollectionMetadata(options.collection, {
          documentCount: stats.documentsProcessed,
          chunkCount: stats.chunksCreated,
          lastIndexedAt: new Date().toISOString()
        }, dimensions);
      }
      stats.duration = Date.now() - startTime;
      stats.successRate = files.length > 0 ? stats.documentsProcessed / files.length : 0;
      this.logger.info({
        stats,
        dryRun: isDryRun
      }, isDryRun ? "Indexing complete (DRY RUN)" : "Indexing complete");
      return stats;
    } catch (error) {
      this.logger.error({ error }, "Indexing failed");
      throw error;
    }
  }
  async processFile(path, content, options) {
    this.logger.debug({ path }, "Processing file");
    const metadata = this.metadataExtractor.extractFrontmatter(content);
    const chunks = this.chunker.chunk(content, path);
    const texts = chunks.map((c) => c.content);
    const embeddings = await this.embeddingProvider.embedBatch(texts);
    const sparseVectors = texts.map((t) => this.sparseVectorProvider.generateSparseVector(t));
    const points = chunks.map((chunk, i) => ({
      id: chunk.id,
      vector: embeddings[i].embedding,
      sparseVector: sparseVectors[i],
      payload: {
        content: chunk.content,
        sourcePath: chunk.documentId,
        heading: chunk.heading,
        level: chunk.level,
        context: chunk.context,
        metadata
      }
    }));
    await this.qdrantProvider.upsertPoints(options.collection, points);
    const totalTokens = embeddings.reduce((sum, result) => sum + result.tokens, 0);
    this.logger.debug({ path, chunks: chunks.length, tokens: totalTokens }, "File processed");
    return { chunksCreated: chunks.length, totalTokens };
  }
  async processFileDryRun(path, content) {
    this.logger.debug({ path }, "Processing file (dry run)");
    const chunks = this.chunker.chunk(content, path);
    const estimatedTokens = chunks.reduce((sum, chunk) => sum + Math.ceil(chunk.content.length / 4), 0);
    this.logger.debug({ path, chunks: chunks.length, estimatedTokens }, "File processed (dry run)");
    return { chunksCreated: chunks.length, totalTokens: estimatedTokens };
  }
  async ensureCollection(options) {
    const strategyName = this.config.embedding.chunking.strategy;
    const dimensions = options.dimensions || this.config.embedding.dimensions;
    const exists = await this.qdrantProvider.collectionExists(options.collection);
    if (!exists) {
      await this.qdrantProvider.createCollection({
        name: options.collection,
        dimensions,
        sparse: this.config.sparse.enabled,
        distance: "Cosine"
      });
      const chunkingConfig = this.config.embedding.chunking;
      const metadata = {
        _isMetadata: true,
        strategyName,
        strategyConfig: chunkingConfig[strategyName] || {},
        createdAt: new Date().toISOString(),
        documentCount: 0,
        chunkCount: 0
      };
      await this.qdrantProvider.upsertCollectionMetadata(options.collection, metadata, dimensions);
      this.logger.info({ collection: options.collection, strategy: strategyName }, "Collection created with strategy metadata");
    } else {
      const existingMetadata = await this.qdrantProvider.getCollectionMetadata(options.collection);
      if (existingMetadata && existingMetadata.strategyName !== strategyName) {
        throw new Error(`Strategy mismatch: collection '${options.collection}' was created with ` + `strategy '${existingMetadata.strategyName}', but current config uses '${strategyName}'. ` + `Delete the collection or use matching strategy.`);
      }
      if (!existingMetadata) {
        this.logger.warn({ collection: options.collection }, "Existing collection has no strategy metadata - adding now");
        const legacyChunkingConfig = this.config.embedding.chunking;
        const metadata = {
          _isMetadata: true,
          strategyName,
          strategyConfig: legacyChunkingConfig[strategyName] || {},
          createdAt: new Date().toISOString(),
          documentCount: 0,
          chunkCount: 0
        };
        await this.qdrantProvider.upsertCollectionMetadata(options.collection, metadata, dimensions);
      }
    }
  }
}

// riffs/vector-indexer/src/core/manage-services.ts
import { spawn } from "node:child_process";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
