class ServiceManager {
  logger;
  config;
  servicesConfig;
  processes;
  started;
  constructor(config, logger) {
    this.config = config;
    this.servicesConfig = config.services;
    this.logger = logger;
    this.processes = new Map;
    this.started = new Set;
  }
  async startServices() {
    if (!this.servicesConfig.autoStart) {
      this.logger.debug("Auto-start disabled, skipping service orchestration");
      return;
    }
    const startTime = Date.now();
    const requiredServices = ["Qdrant"];
    if (this.config.embedding.provider === "llama-cpp") {
      requiredServices.push("Embeddings (llama-server)");
    } else if (this.config.embedding.provider === "ollama") {
      requiredServices.push("Ollama (embeddings)");
    }
    if (this.config.reranker.provider === "llama-cpp") {
      requiredServices.push("Reranker (llama-server)");
    } else if (this.config.reranker.provider === "ollama" && !requiredServices.includes("Ollama (embeddings)")) {
      requiredServices.push("Ollama (reranker)");
    }
    this.logger.info({
      action: "orchestration_start",
      services: requiredServices,
      count: requiredServices.length
    }, `Starting service orchestration: ${requiredServices.join(", ")} (${requiredServices.length} total)`);
    try {
      let currentService = 1;
      const totalServices = requiredServices.length;
      this.logger.info({ progress: `${currentService}/${totalServices}` }, `[${currentService}/${totalServices}] Checking Qdrant`);
      await this.ensureQdrant();
      currentService++;
      if (this.config.embedding.provider === "llama-cpp") {
        this.logger.info({ progress: `${currentService}/${totalServices}` }, `[${currentService}/${totalServices}] Checking Embeddings`);
        await this.ensureLlamaServerEmbeddings();
        currentService++;
      } else if (this.config.embedding.provider === "ollama") {
        this.logger.info({ progress: `${currentService}/${totalServices}` }, `[${currentService}/${totalServices}] Checking Ollama`);
        await this.ensureOllama();
        currentService++;
      }
      if (this.config.reranker.provider === "llama-cpp") {
        this.logger.info({ progress: `${currentService}/${totalServices}` }, `[${currentService}/${totalServices}] Checking Reranker`);
        await this.ensureLlamaServerReranker();
      } else if (this.config.reranker.provider === "ollama" && !this.started.has("ollama")) {
        this.logger.info({ progress: `${currentService}/${totalServices}` }, `[${currentService}/${totalServices}] Checking Ollama`);
        await this.ensureOllama();
      }
      const duration = ((Date.now() - startTime) / 1000).toFixed(1);
      this.logger.info({
        action: "orchestration_complete",
        services: Array.from(this.started),
        healthyCount: this.started.size,
        totalCount: totalServices,
        duration
      }, `All services ready (${this.started.size}/${totalServices} healthy, ${duration}s)`);
    } catch (error) {
      this.logger.error({ error }, "Service orchestration failed");
      throw error;
    }
  }
  async ensureQdrant() {
    this.logger.debug({ service: "qdrant", action: "checking" }, "Checking Qdrant status");
    const containerExists = await this.checkQdrantContainerExists();
    const containerRunning = await this.checkQdrantContainerRunning();
    if (containerExists && containerRunning) {
      this.logger.info({ service: "qdrant", status: "running" }, "Qdrant container running, checking health");
      await this.waitForService("qdrant", () => this.checkQdrant(), "Qdrant");
      this.started.add("qdrant");
      this.logger.info({ service: "qdrant", status: "healthy" }, "Qdrant is healthy");
      return;
    }
    if (containerExists && !containerRunning) {
      this.logger.info({
        service: "qdrant",
        status: "stopped",
        action: "starting"
      }, "Qdrant container stopped, starting it now");
    } else {
      this.logger.info({
        service: "qdrant",
        action: "creating",
        method: "docker-compose"
      }, "Creating Qdrant container via Docker Compose");
    }
    await this.startQdrantDocker();
    this.logger.info({ service: "qdrant", action: "waiting" }, "Waiting for Qdrant to be healthy (may take up to 90s)");
    await this.waitForService("qdrant", () => this.checkQdrant(), "Qdrant");
    this.started.add("qdrant");
    this.logger.info({
      service: "qdrant",
      status: "started",
      host: this.config.qdrant.host,
      port: this.config.qdrant.port,
      storage: this.config.paths.output.qdrant
    }, "Qdrant started successfully");
  }
  async checkQdrantContainerExists() {
    try {
      const containerName = this.servicesConfig.docker.containerName;
      const { stdout } = await this.execAsync(`docker ps -a --filter name=${containerName} --format "{{.Names}}"`);
      return stdout.trim() === containerName;
    } catch {
      return false;
    }
  }
  async checkQdrantContainerRunning() {
    try {
      const containerName = this.servicesConfig.docker.containerName;
      const { stdout } = await this.execAsync(`docker ps --filter name=${containerName} --format "{{.Names}}"`);
      return stdout.trim() === containerName;
    } catch {
      return false;
    }
  }
  async startQdrantDocker() {
    return new Promise((resolve, reject) => {
      const composeFile = this.config.paths.input.compose;
      const proc = spawn("docker", ["compose", "-f", composeFile, "up", "-d"], {
        stdio: "pipe"
      });
      let output = "";
      proc.stdout?.on("data", (data) => {
        output += data.toString();
      });
      proc.stderr?.on("data", (data) => {
        output += data.toString();
      });
      proc.on("close", (code) => {
        if (code === 0) {
          this.logger.debug({ output }, "Docker Compose started");
          resolve();
        } else {
          this.logger.error({ code, output }, "Docker Compose failed");
          reject(new Error(`Docker Compose failed with code ${code}`));
        }
      });
    });
  }
  async ensureLlamaServerEmbeddings() {
    const host = this.config.llamaCppEmbeddings.host;
    this.logger.debug({ service: "llama-server-embeddings", action: "checking" }, "Checking llama-server status");
    if (await this.checkLlamaServer(host)) {
      this.logger.info({ service: "llama-server-embeddings", status: "running", host }, "llama-server (embeddings) already running");
      this.started.add("llama-embeddings");
      return;
    }
    const modelPath = this.config.llamaCppEmbeddings.modelPath.replace("~", homedir());
    if (!modelPath || modelPath.includes("~")) {
      throw new Error("llama_cpp_embeddings.model_path not configured. " + `Find your path: ollama show ${this.config.embedding.model} --modelfile | grep "^FROM "`);
    }
    const port = this.extractPort(this.config.llamaCppEmbeddings.host);
    const hostBinding = this.servicesConfig.llamaServer.hostBinding;
    const gpuLayers = this.servicesConfig.llamaServer.gpuLayers.toString();
    this.logger.info({
      service: "llama-server-embeddings",
      action: "starting",
      model: this.config.embedding.model,
      modelPath,
      port,
      hostBinding,
      gpuLayers
    }, "Starting llama-server for embeddings");
    const args = ["--embeddings", "-m", modelPath, "--port", port, "--host", hostBinding, "-ngl", gpuLayers];
    if (this.servicesConfig.llamaServer.disableLogging) {
      args.push("--log-disable");
    }
    const proc = spawn("llama-server", args, {
      detached: true,
      stdio: "ignore"
    });
    proc.unref();
    this.processes.set("llama-embeddings", proc);
    if (this.servicesConfig.shutdownOnExit && proc.pid !== undefined) {
      this.savePID("llama-embeddings", proc.pid);
    }
    await this.waitForService("llama-embeddings", () => this.checkLlamaServer(host), "llama-server (embeddings)");
    this.started.add("llama-embeddings");
    this.logger.info({
      service: "llama-server-embeddings",
      status: "started",
      port,
      pid: proc.pid
    }, "llama-server (embeddings) ready");
  }
  async ensureLlamaServerReranker() {
    const host = this.config.llamaCppReranker.host;
    this.logger.debug({ service: "llama-server-reranker", action: "checking" }, "Checking llama-server status");
    if (await this.checkLlamaServer(host)) {
      this.logger.info({ service: "llama-server-reranker", status: "running", host }, "llama-server (reranker) already running");
      this.started.add("llama-reranker");
      return;
    }
    const modelPath = this.config.llamaCppReranker.modelPath.replace("~", homedir());
    if (!modelPath || modelPath.includes("~")) {
      throw new Error("llama_cpp_reranker.model_path not configured. " + `Find your path: ollama show ${this.config.reranker.model} --modelfile | grep "^FROM "`);
    }
    const port = this.extractPort(this.config.llamaCppReranker.host);
    const hostBinding = this.servicesConfig.llamaServer.hostBinding;
    const gpuLayers = this.servicesConfig.llamaServer.gpuLayers.toString();
    this.logger.info({
      service: "llama-server-reranker",
      action: "starting",
      model: this.config.reranker.model,
      modelPath,
      port,
      hostBinding,
      gpuLayers
    }, "Starting llama-server for reranking");
    const args = ["-m", modelPath, "--port", port, "--host", hostBinding, "-ngl", gpuLayers];
    if (this.servicesConfig.llamaServer.disableLogging) {
      args.push("--log-disable");
    }
    const proc = spawn("llama-server", args, {
      detached: true,
      stdio: "ignore"
    });
    proc.unref();
    this.processes.set("llama-reranker", proc);
    if (this.servicesConfig.shutdownOnExit && proc.pid !== undefined) {
      this.savePID("llama-reranker", proc.pid);
    }
    await this.waitForService("llama-reranker", () => this.checkLlamaServer(host), "llama-server (reranker)");
    this.started.add("llama-reranker");
    this.logger.info({
      service: "llama-server-reranker",
      status: "started",
      port,
      pid: proc.pid
    }, "llama-server (reranker) ready");
  }
  async ensureOllama() {
    if (this.started.has("ollama")) {
      return;
    }
    this.logger.debug({ service: "ollama", action: "checking" }, "Checking Ollama status");
    if (await this.checkOllama()) {
      this.logger.info({ service: "ollama", status: "running" }, "Ollama already running");
      this.started.add("ollama");
      return;
    }
    this.logger.error({ service: "ollama", status: "not_running" }, "Ollama is not running and cannot be auto-started");
    throw new Error(`Ollama is not running. Please start Ollama manually:
` + `  - macOS: Open Ollama.app
` + "  - CLI: ollama serve");
  }
  async checkQdrant() {
    try {
      const response = await fetch(`http://${this.config.qdrant.host}:${this.config.qdrant.port}/readyz`, {
        signal: AbortSignal.timeout(5000)
      });
      return response.ok;
    } catch {
      return false;
    }
  }
  async checkLlamaServer(host) {
    try {
      const response = await fetch(`${host}/health`, {
        signal: AbortSignal.timeout(5000)
      });
      return response.ok;
    } catch {
      return false;
    }
  }
  async checkOllama() {
    try {
      const response = await fetch(`${this.config.ollama.host}/api/tags`, {
        signal: AbortSignal.timeout(5000)
      });
      return response.ok;
    } catch {
      return false;
    }
  }
  async waitForService(serviceName, checkFn, displayName) {
    const maxWait = this.servicesConfig.startupTimeoutSeconds * 1000;
    const interval = this.servicesConfig.healthCheckIntervalMs;
    const startTime = Date.now();
    let lastLogTime = startTime;
    this.logger.debug({ service: serviceName, timeout: maxWait }, "Waiting for service to be healthy");
    while (Date.now() - startTime < maxWait) {
      if (await checkFn()) {
        const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
        this.logger.info({ service: serviceName, elapsed }, `✓ ${displayName} healthy (${elapsed}s)`);
        return;
      }
      const now = Date.now();
      if (now - lastLogTime >= 5000) {
        const elapsed = ((now - startTime) / 1000).toFixed(0);
        this.logger.info({ service: serviceName, elapsed, maxWait: this.servicesConfig.startupTimeoutSeconds }, `Waiting for ${displayName} health check... ${elapsed}s elapsed`);
        lastLogTime = now;
      }
      await this.sleep(interval);
    }
    throw new Error(`${displayName} failed to start within ${this.servicesConfig.startupTimeoutSeconds} seconds`);
  }
  savePID(serviceName, pid) {
    const dir = this.config.paths.output.pids.replace("~", homedir());
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
    const pidFile = `${dir}/${serviceName}.pid`;
    writeFileSync(pidFile, pid.toString());
    this.logger.debug({ service: serviceName, pid, pidFile }, "PID saved");
  }
  async shutdownDocker() {
    const containerName = this.servicesConfig.docker.containerName;
    try {
      this.logger.info({ container: containerName, action: "stopping" }, "Stopping Docker container");
      await this.execAsync(`docker stop ${containerName}`);
      this.logger.info({ container: containerName, status: "stopped" }, "Docker container stopped");
    } catch (error) {
      this.logger.warn({ container: containerName, error }, "Failed to stop Docker container");
    }
  }
  async shutdownLlamaServers() {
    this.logger.info("Shutting down llama-server processes");
    for (const [name, proc] of this.processes.entries()) {
      try {
        proc.kill();
        this.logger.info({ service: name, pid: proc.pid }, "llama-server process killed");
      } catch (error) {
        this.logger.warn({ service: name, error }, "Failed to kill llama-server process from Map");
      }
    }
    try {
      const { stdout } = await this.execAsync('pgrep -f "llama-server"');
      const pids = stdout.trim().split(`
`).filter((pid) => pid);
      if (pids.length > 0) {
        this.logger.info({ pids }, "Found additional llama-server processes");
        for (const pid of pids) {
          try {
            await this.execAsync(`kill ${pid}`);
            this.logger.info({ pid }, "Killed llama-server process");
          } catch (error) {
            this.logger.warn({ pid, error }, "Failed to kill llama-server process");
          }
        }
      }
    } catch (_error) {
      this.logger.debug("No additional llama-server processes found");
    }
  }
  async shutdownService(serviceName) {
    if (serviceName === "qdrant" || serviceName === "docker") {
      await this.shutdownDocker();
    } else if (serviceName === "embeddings" || serviceName === "llama-embeddings") {
      const proc = this.processes.get("llama-embeddings");
      if (proc) {
        proc.kill();
        this.logger.info({ service: "llama-embeddings", pid: proc.pid }, "Embeddings server stopped");
      } else {
        this.logger.warn({ service: "llama-embeddings" }, "Embeddings server not found");
      }
    } else if (serviceName === "reranker" || serviceName === "llama-reranker") {
      const proc = this.processes.get("llama-reranker");
      if (proc) {
        proc.kill();
        this.logger.info({ service: "llama-reranker", pid: proc.pid }, "Reranker server stopped");
      } else {
        this.logger.warn({ service: "llama-reranker" }, "Reranker server not found");
      }
    } else {
      this.logger.error({ service: serviceName }, "Unknown service name");
      throw new Error(`Unknown service: ${serviceName}`);
    }
  }
  async shutdown(options = {}) {
    if (!options.force && !this.servicesConfig.shutdownOnExit) {
      this.logger.info("Shutdown on exit disabled, leaving services running");
      this.logger.info("Use --force to override this setting");
      return;
    }
    this.logger.info({
      options,
      services: Array.from(this.started)
    }, "Starting service shutdown");
    if (options.service) {
      await this.shutdownService(options.service);
      this.logger.info("Service shutdown complete");
      return;
    }
    if (options.docker || options.all) {
      await this.shutdownDocker();
    }
    if (options.llama || options.all) {
      await this.shutdownLlamaServers();
    }
    if (!options.docker && !options.llama && !options.all && !options.service) {
      await this.shutdownDocker();
      await this.shutdownLlamaServers();
    }
    this.logger.info("Service shutdown complete");
  }
  async execAsync(command) {
    return new Promise((resolve, reject) => {
      const proc = spawn("sh", ["-c", command], { stdio: "pipe" });
      let stdout = "";
      let stderr = "";
      proc.stdout?.on("data", (data) => {
        stdout += data.toString();
      });
      proc.stderr?.on("data", (data) => {
        stderr += data.toString();
      });
      proc.on("close", (code) => {
        if (code === 0) {
          resolve({ stdout, stderr });
        } else {
          reject(new Error(`Command failed with code ${code}: ${stderr}`));
        }
      });
    });
  }
  extractPort(url) {
    const match = url.match(/:(\d+)/);
    return match ? match[1] : "8080";
  }
  sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// riffs/vector-indexer/src/providers/reranker-llama-cpp.ts
class LlamaCppReranker {
  host;
  timeout;
  logger;
  config;
  initialized = false;
  constructor(config, llamaCppConfig, logger) {
    this.config = config;
    this.host = llamaCppConfig.host;
    this.timeout = llamaCppConfig.timeout;
    this.logger = logger;
  }
  async ensureConnection() {
    if (this.initialized)
      return;
    try {
      const response = await fetch(`${this.host}/health`, {
        method: "GET",
        signal: AbortSignal.timeout(5000)
      });
      if (!response.ok) {
        throw new Error(`llama-server health check failed: ${response.status}`);
      }
      this.logger.info({ host: this.host }, "llama-server connection verified");
      this.initialized = true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error({ host: this.host, error: message }, "Failed to connect to llama-server");
      throw new Error(`llama-server not available at ${this.host}. ` + "Ensure llama-server is running with the Qwen3-Reranker model. " + `Error: ${message}`);
    }
  }
  async rerank(query, documents, options) {
    await this.ensureConnection();
    const topK = options?.topK ?? this.config.finalK;
    this.logger.info({ documentCount: documents.length, topK }, "Starting re-ranking with llama.cpp");
    const scores = [];
    for (let i = 0;i < documents.length; i++) {
      const doc = documents[i];
      try {
        const score = await this.scoreDocument(query, doc.content);
        scores.push({ index: i, score });
        this.logger.debug({ docIndex: i, score: score.toFixed(4) }, "Document scored");
      } catch (error) {
        this.logger.warn({ docIndex: i, error }, "Failed to score document");
        scores.push({ index: i, score: 0 });
      }
    }
    scores.sort((a, b) => b.score - a.score);
    const topResults = scores.slice(0, topK);
    this.logger.info({
      inputCount: documents.length,
      outputCount: topResults.length
    }, "Re-ranking complete");
    return topResults.map(({ index, score }) => ({
      index,
      score,
      content: documents[index].content,
      metadata: documents[index].metadata
    }));
  }
  async scoreDocument(query, document2) {
    const prompt = this.buildQwen3Prompt(query, document2);
    const response = await fetch(`${this.host}/completion`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt,
        n_predict: 1,
        n_probs: 10,
        temperature: 0,
        cache_prompt: true
      }),
      signal: AbortSignal.timeout(this.timeout)
    });
    if (!response.ok) {
      throw new Error(`llama-server request failed: ${response.status}`);
    }
    const data = await response.json();
    return this.extractScore(data);
  }
  buildQwen3Prompt(query, document2) {
    const maxDocLength = 2000;
    const truncatedDoc = document2.length > maxDocLength ? `${document2.slice(0, maxDocLength)}...` : document2;
    const instruction = "Given a web search query, retrieve relevant passages that answer the query";
    return `<|im_start|>system
` + "Judge whether the Document meets the requirements based on the Query and the Instruct provided. " + `Note that the answer can only be "yes" or "no".<|im_end|>
` + `<|im_start|>user
` + `<Instruct>: ${instruction}
` + `<Query>: ${query}
` + `<Document>: ${truncatedDoc}<|im_end|>
` + `<|im_start|>assistant
` + `<think>

</think>

`;
  }
  extractScore(response) {
    const topLogprobs = response.completion_probabilities?.[0]?.top_logprobs;
    if (!topLogprobs || topLogprobs.length === 0) {
      this.logger.warn("No completion_probabilities in response, falling back to text parsing");
      return this.parseTextResponse(response.content);
    }
    let yesProb = 0;
    let noProb = 0;
    for (const entry of topLogprobs) {
      const token = entry.token.toLowerCase().trim();
      const prob = Math.exp(entry.logprob);
      if (token === "yes") {
        yesProb = prob;
      } else if (token === "no") {
        noProb = prob;
      }
    }
    if (yesProb === 0 && noProb === 0) {
      const generatedToken = response.content.toLowerCase().trim();
      if (generatedToken.startsWith("yes")) {
        return 1;
      } else if (generatedToken.startsWith("no")) {
        return 0;
      }
      this.logger.warn({ content: response.content, topLogprobs }, "Could not find yes/no probabilities");
      return 0.5;
    }
    const total = yesProb + noProb;
    if (total === 0)
      return 0.5;
    const score = yesProb / total;
    this.logger.debug({
      yesProb: yesProb.toFixed(4),
      noProb: noProb.toFixed(4),
      score: score.toFixed(4)
    }, "Extracted score from logprobs");
    return score;
  }
  parseTextResponse(text) {
    const lower = text.toLowerCase().trim();
    if (lower.startsWith("yes"))
      return 1;
    if (lower.startsWith("no"))
      return 0;
    return 0.5;
  }
  async selectBestModel() {
    return this.config.model;
  }
}

// riffs/vector-indexer/src/providers/reranker-ollama.ts
import { totalmem } from "node:os";
class OllamaReranker {
  ollama;
  logger;
  config;
  constructor(config, ollamaHost, logger) {
    this.config = config;
    this.logger = logger;
    this.ollama = createOllama({
      baseURL: ollamaHost
    });
  }
  async rerank(query, documents, options) {
    const model = options?.model ?? this.config.model;
    const topK = options?.topK ?? this.config.finalK;
    this.logger.info({ model, documentCount: documents.length, topK }, "Starting re-ranking");
    const scores = [];
    for (let i = 0;i < documents.length; i++) {
      const doc = documents[i];
      const prompt = this.buildRerankPrompt(query, doc.content);
      try {
        const { text } = await generateText({
          model: this.ollama.languageModel(model),
          prompt,
          maxOutputTokens: 100,
          temperature: 0
        });
        const score = this.parseScore(text);
        scores.push({ index: i, score });
        this.logger.debug({ docIndex: i, score }, "Document scored");
      } catch (error) {
        this.logger.warn({ docIndex: i, error }, "Failed to score document");
        scores.push({ index: i, score: 0 });
      }
    }
    scores.sort((a, b) => b.score - a.score);
    const topResults = scores.slice(0, topK);
    this.logger.info({
      model,
      inputCount: documents.length,
      outputCount: topResults.length
    }, "Re-ranking complete");
    return topResults.map(({ index, score }) => ({
      index,
      score,
      content: documents[index].content,
      metadata: documents[index].metadata
    }));
  }
  buildRerankPrompt(query, document2) {
    const maxDocLength = 2000;
    const truncatedDoc = document2.length > maxDocLength ? `${document2.slice(0, maxDocLength)}...` : document2;
    return `You are a strict relevance assessor. Evaluate if a document answers a query.

SCORING CRITERIA:
0-2: Completely irrelevant or off-topic
3-4: Related concepts but does NOT answer the query
5-6: Tangentially relevant, missing key information
7-8: Relevant, partially answers the query
9-10: DIRECTLY and COMPLETELY answers the query

Be STRICT. Most documents score 3-6. Score 9-10 ONLY if document is a near-perfect match.

Query: ${query}

Document:
${truncatedDoc}

In one sentence, explain relevance. Then output ONLY a number (0-10) on a new line.

Assessment:`;
  }
  parseScore(text) {
    const trimmed = text.trim();
    const lines = trimmed.split(`
`);
    for (let i = lines.length - 1;i >= 0; i--) {
      const line = lines[i].trim();
      const match = line.match(/^(\d+(?:\.\d+)?)$/);
      if (match) {
        return Math.min(10, Math.max(0, Number.parseFloat(match[1])));
      }
    }
    const anyMatch = trimmed.match(/(\d+(?:\.\d+)?)/);
    if (anyMatch) {
      return Math.min(10, Math.max(0, Number.parseFloat(anyMatch[1])));
    }
    this.logger.warn({ text: trimmed.slice(0, 100) }, "Could not parse score from model output");
    return 0;
  }
  async selectBestModel() {
    const totalMemoryGb = totalmem() / 1024 ** 3;
    this.logger.debug({ totalMemoryGb, threshold: this.config.memoryThresholdGb }, "Checking available memory");
    if (totalMemoryGb >= this.config.memoryThresholdGb) {
      this.logger.info({ model: this.config.highMemoryModel }, "Using high-memory model");
      return this.config.highMemoryModel;
    }
    this.logger.info({ model: this.config.model }, "Using standard model");
    return this.config.model;
  }
}

// riffs/vector-indexer/src/providers/reranker.ts
class Reranker {
  provider;
  logger;
  constructor(config, logger) {
    this.logger = logger;
    const providerType = config.reranker.provider ?? "ollama";
    switch (providerType) {
      case "llama-cpp":
        this.logger.info({ provider: "llama-cpp" }, "Initializing llama.cpp reranker provider");
        this.provider = new LlamaCppReranker(config.reranker, config.llamaCppReranker, logger);
        break;
      default:
        this.logger.info({ provider: "ollama" }, "Initializing Ollama reranker provider");
        this.provider = new OllamaReranker(config.reranker, config.ollama.host, logger);
        break;
    }
  }
  async rerank(query, documents, options) {
    return this.provider.rerank(query, documents, options);
  }
  async selectBestModel() {
    if (this.provider.selectBestModel) {
      return this.provider.selectBestModel();
    }
    throw new Error("Provider does not support model selection");
  }
}

// riffs/vector-indexer/src/core/searcher.ts
class Searcher {
  logger;
  _config;
  embeddingProvider;
  sparseVectorProvider;
  qdrantProvider;
  reranker;
  constructor(config, logger) {
    this._config = config;
    this.logger = logger;
    this.embeddingProvider = new EmbeddingProvider(config, logger);
    this.sparseVectorProvider = new SparseVectorProvider(config.sparse, logger);
    this.qdrantProvider = new QdrantProvider(config.qdrant, logger);
    this.reranker = new Reranker(config, logger);
  }
  async search(query, options) {
    this.logger.info({
      query,
      collection: options.collection,
      topK: options.topK,
      rerank: options.rerank
    }, "Starting search");
    try {
      const { embedding: denseVector } = await this.embeddingProvider.embed(query);
      const sparseVector = this.sparseVectorProvider.generateSparseVector(query);
      const results = await this.qdrantProvider.hybridSearch(options.collection, {
        denseVector,
        sparseVector,
        denseWeight: options.denseWeight,
        sparseWeight: options.sparseWeight,
        limit: options.topK,
        filter: options.filter
      });
      this.logger.debug({ resultCount: results.length }, "Initial results retrieved");
      if (options.rerank && results.length > 0) {
        const reranked = await this.reranker.rerank(query, results.map((r) => ({
          content: r.content,
          metadata: r.metadata
        })), {
          topK: options.finalK,
          model: options.rerankerModel
        });
        this.logger.info({ rerankedCount: reranked.length }, "Results re-ranked");
        return reranked.map((r) => ({
          id: results[r.index].id,
          score: r.score,
          content: r.content,
          metadata: r.metadata
        }));
      }
      return results.slice(0, options.finalK);
    } catch (error) {
      this.logger.error({ error }, "Search failed");
      throw error;
    }
  }
  getConfig() {
    return this._config;
  }
}

